begin;select plan(46);
select has_table('public','identity_monitoring_observations','observations exist');select has_table('public','identity_monitoring_incidents','incidents exist');select has_table('public','identity_monitoring_actions','actions exist');select has_table('public','creator_security_alerts','alerts exist');
select ok((select relforcerowsecurity from pg_class where oid='public.identity_monitoring_observations'::regclass),'observation RLS forced');select ok((select relforcerowsecurity from pg_class where oid='public.identity_monitoring_incidents'::regclass),'incident RLS forced');select ok((select relforcerowsecurity from pg_class where oid='public.identity_monitoring_actions'::regclass),'action RLS forced');select ok((select relforcerowsecurity from pg_class where oid='public.creator_security_alerts'::regclass),'alert RLS forced');
select table_privs_are('public','identity_monitoring_observations','anon',array[]::text[],'anon cannot read observations');select table_privs_are('public','identity_monitoring_incidents','anon',array[]::text[],'anon cannot read incidents');select function_privs_are('public','process_identity_observation',array['uuid'],'authenticated',array[]::text[],'browser cannot process authoritative observations');select function_privs_are('public','claim_identity_monitoring',array['integer','uuid'],'service_role',array['EXECUTE'],'worker claim is service-only');
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,recovery_token,email_change_token_new,email_change)values('00000000-0000-0000-0000-000000000000','c6000000-0000-4000-8000-000000000001','authenticated','authenticated','monitor-owner@example.com',crypt('pw',gen_salt('bf')),now(),'{}','{}',now(),now(),'','','',''),('00000000-0000-0000-0000-000000000000','c6000000-0000-4000-8000-000000000002','authenticated','authenticated','monitor-other@example.com',crypt('pw',gen_salt('bf')),now(),'{}','{}',now(),now(),'','','','');
update public.creators set display_name='Monitor Creator',public_slug='monitor-creator',public_profile_enabled=true where owner_user_id='c6000000-0000-4000-8000-000000000001';select set_config('tests.monitor_creator',(select id::text from public.creators where public_slug='monitor-creator'),true);
set local role authenticated;select set_config('request.jwt.claim.sub','c6000000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"c6000000-0000-4000-8000-000000000001","role":"authenticated"}',true);select lives_ok($$select public.ensure_creator_identity_profile()$$,'owner creates identity profile');select throws_ok($$select public.ingest_identity_observation((select id from public.creator_identity_profiles),'provider_grant_revoked','high','creator_report')$$,'23514','creator report cannot assert authoritative state','creator cannot report revocation');select lives_ok($$select public.ingest_identity_observation((select id from public.creator_identity_profiles),'sync_failure','low','creator_report',p_metadata=>'{"report_note":"provider unavailable"}')$$,'creator may submit unverified report');select is((select source from public.identity_monitoring_observations),'creator_report','creator report is tagged');
reset role;insert into public.connected_accounts(id,creator_id,platform,account_type,label,url,is_primary,external_account_id,external_account_name,external_account_url,connection_health,provider_status)values('c6100000-0000-4000-8000-000000000001',current_setting('tests.monitor_creator')::uuid,'youtube','official','@monitor','https://youtube.com/channel/monitor',true,'monitor-channel','Monitor Creator','https://youtube.com/channel/monitor','healthy','ready');
set local role service_role;select set_config('request.jwt.claim.role','service_role',true);select public.sync_identity_account_from_connection('c6100000-0000-4000-8000-000000000001');update public.creator_identity_accounts set official=true,primary_for_provider=true,public_visible=true,next_monitor_at=now()-interval'1 minute';select is((select count(*)::integer from public.claim_identity_monitoring(10,'c6200000-0000-4000-8000-000000000001')),1,'due account is leased');update public.creator_identity_accounts set monitor_lease_expires_at=now()-interval'1 minute';select is((select count(*)::integer from public.claim_identity_monitoring(10,'c6200000-0000-4000-8000-000000000002')),1,'stale lease is recovered');
select lives_ok($$select public.ingest_identity_observation((select id from public.creator_identity_profiles),'account_handle_changed','low','identity_sync_worker','handle-event',(select id from public.creator_identity_accounts),null,'old','new',now(),'{"handle":"@new-monitor"}')$$,'worker ingests handle change');select is((public.ingest_identity_observation((select id from public.creator_identity_profiles),'account_handle_changed','low','identity_sync_worker','handle-event',(select id from public.creator_identity_accounts),null,'old','new',now(),'{"handle":"@new-monitor"}')->>'inserted')::boolean,false,'duplicate source event deduplicates');select lives_ok($$select public.process_identity_observation((select id from public.identity_monitoring_observations where source_event_id='handle-event'))$$,'handle observation processes');select is((select display_handle from public.creator_identity_accounts),'@new-monitor','handle updates existing identity');select is((select count(*)::integer from public.creator_identity_accounts),1,'handle change creates no duplicate identity');
select lives_ok($$select public.ingest_identity_observation((select id from public.creator_identity_profiles),'stable_identity_mismatch','critical','identity_sync_worker','mismatch-one',(select id from public.creator_identity_accounts),null,'safe-one','safe-two',now(),'{"stable_id":"different-channel"}')$$,'stable mismatch ingested');select lives_ok($$select public.process_identity_observation((select id from public.identity_monitoring_observations where source_event_id='mismatch-one'))$$,'stable mismatch processes');select is((select count(*)::integer from public.identity_monitoring_incidents),1,'critical incident created');select ok((select not official and not primary_for_provider and not public_visible and stable_provider_account_id='monitor-channel'from public.creator_identity_accounts),'badge suppressed without overwriting stable ID');select is((select count(*)::integer from public.creator_security_alerts),1,'private creator alert created');select ok(exists(select 1 from public.identity_monitoring_actions where action_type='trust_reevaluation_requested'),'trust reevaluation requested');
select lives_ok($$select public.ingest_identity_observation((select id from public.creator_identity_profiles),'stable_identity_mismatch','critical','identity_sync_worker','mismatch-two',(select id from public.creator_identity_accounts),null,'safe-two','safe-three',now(),'{"stable_id":"third-channel"}')$$,'repeated mismatch ingested');select lives_ok($$select public.process_identity_observation((select id from public.identity_monitoring_observations where source_event_id='mismatch-two'))$$,'repeated mismatch processes');select is((select count(*)::integer from public.identity_monitoring_incidents),1,'repeated mismatch correlates to one incident');select is((select count(*)::integer from public.creator_security_alerts),1,'alert deduplicates by incident');select is((select count(*)::integer from public.creator_emergencies),0,'monitoring creates no emergency automatically');select throws_ok($$update public.identity_monitoring_actions set status='forged'$$,'55000','emergency history is immutable','actions are append-only');reset role;select is((select count(*)::integer from public.update_deliveries),0,'monitoring queues no follower deliveries');
set local role authenticated;select set_config('request.jwt.claim.sub','c6000000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"c6000000-0000-4000-8000-000000000001","role":"authenticated"}',true);select lives_ok($$select public.update_monitoring_incident((select id from public.identity_monitoring_incidents),'acknowledge')$$,'owner acknowledges incident');select is((select status from public.identity_monitoring_incidents),'acknowledged','incident acknowledged');select throws_ok($$select public.update_monitoring_incident((select id from public.identity_monitoring_incidents),'dismiss')$$,'42501','high-risk incidents cannot be dismissed','critical incident cannot be dismissed');select lives_ok($$select public.prepare_monitoring_emergency((select id from public.identity_monitoring_incidents))$$,'owner prepares emergency draft');select is((select lifecycle_status from public.creator_emergencies),'draft','prepared emergency remains draft');reset role;select is((select count(*)::integer from public.update_deliveries),0,'draft preparation sends no delivery');set local role authenticated;select set_config('request.jwt.claim.sub','c6000000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"c6000000-0000-4000-8000-000000000001","role":"authenticated"}',true);select lives_ok($$select public.update_monitoring_incident((select id from public.identity_monitoring_incidents),'resolve','authoritative_recovery_confirmed')$$,'owner resolves after recovery');select is((select status from public.identity_monitoring_incidents),'resolved','incident resolved');
select set_config('request.jwt.claim.sub','c6000000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"c6000000-0000-4000-8000-000000000002","role":"authenticated"}',true);select is((select count(*)::integer from public.identity_monitoring_incidents),0,'other creator cannot read incident');select is((select count(*)::integer from public.creator_security_alerts),0,'other creator cannot read alerts');
select * from finish();rollback;
